diff --git a/src/commonMain/kotlin/io/github/kevincianfarini/cardiologist/PulseSchedule.kt b/src/commonMain/kotlin/io/github/kevincianfarini/cardiologist/PulseSchedule.kt
index c6baa1b..8f48957 100644
--- a/src/commonMain/kotlin/io/github/kevincianfarini/cardiologist/PulseSchedule.kt
+++ b/src/commonMain/kotlin/io/github/kevincianfarini/cardiologist/PulseSchedule.kt
@@ -56,6 +56,251 @@ public class PulseSchedule internal constructor(
         // Don't check if onDaysOfWeek is empty because an empty set is equivalent to the wildcard `*` value in cron
         // expressions.
     }
+        public companion object {
+            /**
+             * Parse a standard 5-field cron expression into a [PulseSchedule].
+             * 
+             * Format: minute hour day-of-month month day-of-week
+             * 
+             * Each field supports:
+             * - Wildcard: *
+             * - Single value: 5
+             * - Multiple values: 1,5,10
+             * - Ranges: 1-5
+             * - Mixed: 1-5,10,15-20
+             * 
+             * Month field accepts: 1-12 or JAN, FEB, MAR, APR, MAY, JUN, JUL, AUG, SEP, OCT, NOV, DEC (case-insensitive)
+             * Day-of-week field accepts: 0-6 or MON, TUE, WED, THU, FRI, SAT, SUN (case-insensitive)
+             * 
+             * @throws IllegalArgumentException if the expression is invalid or has out-of-bounds values
+             */
+            public fun parseCron(expression: String): PulseSchedule {
+                if (expression.isEmpty()) {
+                    throw IllegalArgumentException("'' is not a valid cron expression.")
+                }
+
+                val fields = expression.trim().split(Regex("\\s+"))
+                if (fields.size != 5) {
+                    throw IllegalArgumentException("'$expression' is not a valid cron expression.")
+                }
+
+                val errors = mutableListOf<Int>()
+
+                // Parse minute (0-59)
+                val minutes = try {
+                    parseField(fields[0], 0..59)
+                } catch (e: IllegalArgumentException) {
+                    errors.add(0)
+                    null
+                }
+
+                // Parse hour (0-23)
+                val hours = try {
+                    parseField(fields[1], 0..23)
+                } catch (e: IllegalArgumentException) {
+                    errors.add(1)
+                    null
+                }
+
+                // Parse day of month (1-31)
+                val daysOfMonth = try {
+                    parseField(fields[2], 1..31)
+                } catch (e: IllegalArgumentException) {
+                    errors.add(2)
+                    null
+                }
+
+                // Parse month (1-12 or names)
+                val months = try {
+                    parseMonthField(fields[3])
+                } catch (e: IllegalArgumentException) {
+                    errors.add(3)
+                    null
+                }
+
+                // Parse day of week (0-6 or names)
+                val daysOfWeek = try {
+                    parseDayOfWeekField(fields[4])
+                } catch (e: IllegalArgumentException) {
+                    errors.add(4)
+                    null
+                }
+
+                if (errors.isNotEmpty()) {
+                    val errorMessage = fields.mapIndexed { index, field ->
+                        if (index in errors) "<<$field>>" else field
+                    }.joinToString(" ")
+                    throw IllegalArgumentException("Cron expression is malformed: $errorMessage")
+                }
+
+                return PulseSchedule(
+                    atSeconds = setOf(0),
+                    atMinutes = minutes!!,
+                    atHours = hours!!,
+                    onDaysOfMonth = daysOfMonth!!,
+                    inMonths = months!!,
+                    onDaysOfWeek = daysOfWeek!!
+                )
+            }
+
+            private fun parseField(field: String, range: IntRange): Set<Int> {
+                if (field == "*") {
+                    return range.toSet()
+                }
+
+                val result = mutableSetOf<Int>()
+                val parts = field.split(",")
+
+                for (part in parts) {
+                    if (part.isEmpty()) {
+                        throw IllegalArgumentException("Empty part in field")
+                    }
+
+                    if ("-" in part) {
+                        val rangeParts = part.split("-")
+                        if (rangeParts.size != 2 || rangeParts[0].isEmpty() || rangeParts[1].isEmpty()) {
+                            throw IllegalArgumentException("Invalid range: $part")
+                        }
+
+                        val start = rangeParts[0].toIntOrNull() 
+                            ?: throw IllegalArgumentException("Invalid number: ${rangeParts[0]}")
+                        val end = rangeParts[1].toIntOrNull() 
+                            ?: throw IllegalArgumentException("Invalid number: ${rangeParts[1]}")
+
+                        if (start !in range || end !in range || start > end) {
+                            throw IllegalArgumentException("Invalid range: $part")
+                        }
+
+                        result.addAll(start..end)
+                    } else {
+                        val value = part.toIntOrNull() 
+                            ?: throw IllegalArgumentException("Invalid number: $part")
+                        if (value !in range) {
+                            throw IllegalArgumentException("Value out of range: $value")
+                        }
+                        result.add(value)
+                    }
+                }
+
+                return result
+            }
+
+            private fun parseMonthField(field: String): Set<Month> {
+                if (field == "*") {
+                    return Month.entries.toSet()
+                }
+
+                val monthNames = mapOf(
+                    "jan" to Month.JANUARY,
+                    "feb" to Month.FEBRUARY,
+                    "mar" to Month.MARCH,
+                    "apr" to Month.APRIL,
+                    "may" to Month.MAY,
+                    "jun" to Month.JUNE,
+                    "jul" to Month.JULY,
+                    "aug" to Month.AUGUST,
+                    "sep" to Month.SEPTEMBER,
+                    "oct" to Month.OCTOBER,
+                    "nov" to Month.NOVEMBER,
+                    "dec" to Month.DECEMBER
+                )
+
+                val result = mutableSetOf<Month>()
+                val parts = field.split(",")
+
+                for (part in parts) {
+                    if (part.isEmpty()) {
+                        throw IllegalArgumentException("Empty part in field")
+                    }
+
+                    if ("-" in part) {
+                        val rangeParts = part.split("-")
+                        if (rangeParts.size != 2 || rangeParts[0].isEmpty() || rangeParts[1].isEmpty()) {
+                            throw IllegalArgumentException("Invalid range: $part")
+                        }
+
+                        val start = parseMonthValue(rangeParts[0], monthNames)
+                        val end = parseMonthValue(rangeParts[1], monthNames)
+
+                        if (start.number > end.number) {
+                            throw IllegalArgumentException("Invalid range: $part")
+                        }
+
+                        (start.number..end.number).forEach { result.add(Month(it)) }
+                    } else {
+                        result.add(parseMonthValue(part, monthNames))
+                    }
+                }
+
+                return result
+            }
+
+            private fun parseMonthValue(value: String, monthNames: Map<String, Month>): Month {
+                return monthNames[value.lowercase()] 
+                    ?: value.toIntOrNull()?.let { 
+                        if (it in 1..12) Month(it) else throw IllegalArgumentException("Invalid month: $value")
+                    }
+                    ?: throw IllegalArgumentException("Invalid month: $value")
+            }
+
+            private fun parseDayOfWeekField(field: String): Set<DayOfWeek> {
+                if (field == "*") {
+                    return emptySet()
+                }
+
+                val dayNames = mapOf(
+                    "mon" to DayOfWeek.MONDAY,
+                    "tue" to DayOfWeek.TUESDAY,
+                    "wed" to DayOfWeek.WEDNESDAY,
+                    "thu" to DayOfWeek.THURSDAY,
+                    "fri" to DayOfWeek.FRIDAY,
+                    "sat" to DayOfWeek.SATURDAY,
+                    "sun" to DayOfWeek.SUNDAY
+                )
+
+                val result = mutableSetOf<DayOfWeek>()
+                val parts = field.split(",")
+
+                for (part in parts) {
+                    if (part.isEmpty()) {
+                        throw IllegalArgumentException("Empty part in field")
+                    }
+
+                    if ("-" in part) {
+                        val rangeParts = part.split("-")
+                        if (rangeParts.size != 2 || rangeParts[0].isEmpty() || rangeParts[1].isEmpty()) {
+                            throw IllegalArgumentException("Invalid range: $part")
+                        }
+
+                        val start = parseDayOfWeekValue(rangeParts[0], dayNames)
+                        val end = parseDayOfWeekValue(rangeParts[1], dayNames)
+
+                        // Handle SUN-SAT (7-6) special case - this should include all days
+                        if (start == DayOfWeek.SUNDAY && end == DayOfWeek.SATURDAY) {
+                            result.addAll(DayOfWeek.entries)
+                        } else if (start.isoDayNumber > end.isoDayNumber) {
+                            throw IllegalArgumentException("Invalid range: $part")
+                        } else {
+                            (start.isoDayNumber..end.isoDayNumber).forEach { result.add(DayOfWeek(it)) }
+                        }
+                    } else {
+                        result.add(parseDayOfWeekValue(part, dayNames))
+                    }
+                }
+
+                return result
+            }
+
+            private fun parseDayOfWeekValue(value: String, dayNames: Map<String, DayOfWeek>): DayOfWeek {
+                return dayNames[value.lowercase()] 
+                    ?: value.toIntOrNull()?.let { 
+                        if (it in 0..6) DayOfWeek(if (it == 0) 7 else it) else throw IllegalArgumentException("Invalid day of week: $value")
+                    }
+                    ?: throw IllegalArgumentException("Invalid day of week: $value")
+            }
+        }
+
+
 }

 public class PulseScheduleBuilder internal constructor() {
